"""User-facing repair steps based on reported state, without guessing bans."""
from urllib.parse import urlencode

def diagnose(row, site):
    state=row.get('state','UNKNOWN');platform=row.get('platform','')
    support=site+'/?'+urlencode({'matrix_account_help':row.get('key','')})
    relogin=site+'/?'+urlencode({'matrix_reconnect':platform,'matrix_account':row.get('login_id','')})
    if state=='CONNECTED':
        return dict(category='connected',title='Связь восстановлена',reason='Мост подтвердил подключение аккаунта.',
                    steps=['Повторный вход не требуется.','Проверьте поступление нового сообщения.'],action_url=support,action_label='Открыть аккаунт')
    if state in ['BAD_CREDENTIALS','LOGGED_OUT','WRONG_ACCOUNT']:
        steps={'whatsapp':['Откройте «Переподключить» в Matrix для этого номера.','Подтвердите подключение WhatsApp на телефоне и отсканируйте новый QR-код.'],
               'telegram':['Откройте «Переподключить» в Matrix.','Войдите в нужный Telegram-аккаунт через QR или номер; при запросе введите код и пароль двухэтапной проверки.'],
               'imo':['Откройте «Переподключить» и выберите этот IMO-аккаунт.','Подтвердите вход с телефона через QR-код.'],
               'email':['Откройте Gmail в настройках подключения Matrix.','Введите адрес этого ящика и действующий пароль приложения Google.']}.get(platform,
               ['Откройте «Переподключить» в Matrix.','Выполните вход в этот аккаунт и подтвердите запросы безопасности сервиса.'])
        steps+=['Дождитесь зелёного индикатора и проверьте новое сообщение.','Если аккаунт больше не нужен, используйте «Удалить подключение».']
        return dict(category='authentication',title='Нужен повторный вход',reason='Мост сообщает, что действующей авторизации нет. Точную причину её потери сервис не сообщил.',steps=steps,action_url=relogin,action_label='Переподключить аккаунт')
    if state=='STALE':
        return dict(category='stale',title='Статус давно не проверялся',reason='Данные мониторинга устарели; фактическое подключение аккаунта неизвестно.',
                    steps=['Нажмите «Проверить» в Matrix.','Проверьте доступность сервера Matrix и службы мониторинга.','Если устарели все аккаунты одновременно, начните с сервера и сети.'],action_url=support,action_label='Проверить состояние')
    if state=='UNREACHABLE':
        return dict(category='bridge',title='Нет ответа от моста',reason='Монитор Matrix не смог получить состояние от службы этого мессенджера. Авторизация аккаунта не проверена.',
                    steps=['Проверьте доступность службы моста и сети сервера.','Нажмите «Проверить» после восстановления службы.','Выполняйте повторный вход, только если затем появится «Нужен повторный вход».'],action_url=support,action_label='Проверить состояние')
    if state=='MISSING':
        return dict(category='missing',title='Подключение не найдено',reason='Аккаунта нет в последнем полученном списке; подтверждения удаления пока нет.',
                    steps=['Обновите список подключений в Matrix.','Если вы удаляли аккаунт, завершите удаление через «Удалить подключение».'],action_url=support,action_label='Открыть настройки аккаунта')
    return dict(category='connection',title='Связь не подтверждена',reason='Мост сообщил о разрыве соединения или ошибке. Это не подтверждение блокировки аккаунта.',
                steps=['Подождите автоматического восстановления и нажмите «Проверить».','Проверьте сеть сервера и работу родного приложения.','Если ошибка сохраняется, передайте поддержке код состояния из этого сообщения.'],action_url=support,action_label='Проверить состояние')
